static int treefile_zero_range(CLIENT *client, uint64_t pos, uint64_t len)
{
	char zeros[TREEPAGESIZE];

	memset(zeros, 0, sizeof(zeros));
	while (len > 0) {
		int fd = treefile_getfd(client, (off_t)pos, 1);
		size_t chunk = TREEPAGESIZE - (pos % TREEPAGESIZE);

		if (chunk > len)
			chunk = len;
		if (fd < 0 || pwrite(fd, zeros, chunk, pos % TREEPAGESIZE) != (ssize_t)chunk)
			return -1;
		pos += chunk;
		len -= chunk;
	}
	return 0;
}

int treefiles_write_zeroes(struct nbd_request *req, CLIENT *client, int fua)
{
	uint64_t from = req->from;
	uint64_t len = req->len;
	uint64_t end = from + len;
	uint64_t first_full = (from + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t past_last_full = end / TREEPAGESIZE;
	uint64_t blocknr;

	if (first_full >= past_last_full)
		return treefile_zero_range(client, from, len);

	if (from < first_full * TREEPAGESIZE &&
	    treefile_zero_range(client, from, first_full * TREEPAGESIZE - from))
		return -1;
	for (blocknr = first_full; blocknr < past_last_full; blocknr++) {
		treefile_drop_block(client, blocknr);
		delete_treefile(client->exportname, (off_t)client->exportsize, blocknr * TREEPAGESIZE);
	}
	if (past_last_full * TREEPAGESIZE < end &&
	    treefile_zero_range(client, past_last_full * TREEPAGESIZE, end - past_last_full * TREEPAGESIZE))
		return -1;

	if ((client->server->flags & F_SYNC) || fua)
		return treefiles_flush(client);
	return 0;
}
