arguments.content:
/*
 * Tree files support.
 *
 * A treefiles export stores its data in a tree of small fixed-size block
 * files rather than in one large file. The exportname of such an export
 * is a directory; each directory level holds at most TREEDIRSIZE entries,
 * and each block file at the leaves holds TREEPAGESIZE bytes of export
 * data. Depending on the total size of the export, several levels of
 * subdirectories (named TREEXXXX) are nested below the export directory,
 * with the block files (named FILEXXXX) as the leaves of the tree.
 *
 * Block files and the directories leading to them are created on demand
 * when data is written, and block files are removed again when the
 * corresponding block is trimmed or zeroed out. Blocks without a block
 * file read back as all zeroes.
 */

#include "config.h"
#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include <glib.h>

#include "nbd-debug.h"
#include "treefiles.h"

/** maximum size of a buffer holding the full path of a block file */
#define TREE_PATH_MAX 4096

/** maximum number of block file descriptors kept open per client */
#define TREEFILE_MAX_FDS 1024

/**
 * Compute the number of levels of TREEXXXX subdirectories needed for an
 * export of the given size. If the export holds at most TREEDIRSIZE
 * blocks, no subdirectories are needed and the block files live directly
 * below the export directory.
 *
 * @param size the total size of the export in bytes
 * @return the number of directory levels between the export directory
 * and the block files
 **/
static int tree_depth(off_t size) {
	uint64_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t capacity = TREEDIRSIZE;
	int depth = 0;

	while (capacity < blocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}
	return depth;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of a treefiles export. The path is appended to the directory
 * already contained in the name buffer.
 *
 * @param name on input a buffer holding the path of the export
 * directory, on output a buffer holding the full path of the block file
 * @param lenmax the size of the name buffer
 * @param size the total size of the export in bytes
 * @param pos a byte offset into the export
 * @param ppos if not NULL, receives the offset of pos within the block
 * file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	uint64_t blocknr = pos / TREEPAGESIZE;
	int depth = tree_depth(size);
	uint64_t divisor = 1;
	int len = strlen(name);
	int i;

	for (i = 0; i < depth; i++)
		divisor *= TREEDIRSIZE;

	for (i = depth; i >= 0; i--) {
		unsigned int entry = (blocknr / divisor) % TREEDIRSIZE;

		if (i > 0)
			snprintf(name + len, lenmax - len, "/TREE%04X", entry);
		else
			snprintf(name + len, lenmax - len, "/FILE%04X", entry);
		len = strlen(name);
		divisor /= TREEDIRSIZE;
	}

	if (ppos)
		*ppos = pos % TREEPAGESIZE;
}

/**
 * Create all directories in the given path. Existing directories are
 * silently left alone.
 *
 * @param path the path whose directory components should be created;
 * temporarily modified by this function
 **/
void mkdir_path(char *path) {
	char *p = path;

	while ((p = strchr(p + 1, '/')) != NULL) {
		*p = '\0';
		mkdir(path, 0700);
		*p = '/';
	}
	mkdir(path, 0700);
}

/**
 * Open the block file holding the data at a given offset of a treefiles
 * export. The directories leading to the block file are created if they
 * do not exist yet.
 *
 * @param name the path of the export directory
 * @param mode open mode for the block file; if it contains O_CREAT, the
 * file is created (or truncated to the size of the data it should hold)
 * when it does not exist yet
 * @param size the total size of the export in bytes
 * @param pos a byte offset into the export
 * @param mutex mutex serializing directory and file creation between
 * threads
 * @return a file descriptor for the block file, or -1 in case of error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[TREE_PATH_MAX];
	char *lastsep;
	off_t ppos;
	int depth;
	int fd;

	depth = tree_depth(size);
	/* every tree level adds a "/TREEXXXX" or "/FILEXXXX" component */
	if (strlen(name) + (depth + 1) * 9 + 1 > sizeof(path)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);

	lastsep = strrchr(path, '/');
	*lastsep = '\0';
	pthread_mutex_lock(mutex);
	mkdir_path(path);
	*lastsep = '/';
	fd = open(path, mode, 0600);
	if (fd >= 0 && (mode & O_CREAT)) {
		/* give the block file the size of the data it should
		 * hold, so that reads of never-written data at the end
		 * of the export succeed */
		off_t blockstart = (pos / TREEPAGESIZE) * TREEPAGESIZE;
		off_t blocklen = TREEPAGESIZE;

		if (size - blockstart < blocklen)
			blocklen = size - blockstart;
		ftruncate(fd, blocklen);
	}
	pthread_mutex_unlock(mutex);

	return fd;
}

/**
 * Delete the block file holding the data at a given offset of a
 * treefiles export. It is not an error if the block file does not
 * exist.
 *
 * @param name the path of the export directory
 * @param size the total size of the export in bytes
 * @param pos a byte offset into the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[TREE_PATH_MAX];
	off_t ppos;

	if (strlen(name) + (tree_depth(size) + 1) * 9 + 1 > sizeof(path))
		return;
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);
	if (unlink(path) < 0 && errno != ENOENT)
		DEBUG("could not delete treefile %s: %s\n", path, strerror(errno));
}

/**
 * Initialize the treefiles state of a client.
 *
 * @param client the client whose state to initialize
 **/
void treefiles_client_init(CLIENT *client) {
	pthread_mutex_init(&client->treefile_lock, NULL);
	client->treefdcache = g_hash_table_new_full(g_int64_hash,
			g_int64_equal, g_free, NULL);
}

static gboolean treefile_close_cb(gpointer key, gpointer value, gpointer user_data) {
	close(GPOINTER_TO_INT(value));
	return TRUE;
}

/**
 * Close all cached block file descriptors of a client and free its
 * treefiles state.
 *
 * @param client the client whose state to free
 **/
void treefiles_client_free(CLIENT *client) {
	if (client->treefdcache) {
		g_hash_table_foreach_remove(client->treefdcache,
				treefile_close_cb, NULL);
		g_hash_table_destroy(client->treefdcache);
		client->treefdcache = NULL;
	}
	pthread_mutex_destroy(&client->treefile_lock);
}

struct treefile_entry {
	uint64_t blocknr;
	int fd;
};

static gboolean treefile_find_one(gpointer key, gpointer value, gpointer user_data) {
	struct treefile_entry *entry = user_data;

	entry->blocknr = *(uint64_t *)key;
	entry->fd = GPOINTER_TO_INT(value);
	return TRUE;
}

/**
 * Drop one arbitrary entry from the descriptor cache to keep the number
 * of open file descriptors bounded. The caller must hold
 * client->treefile_lock.
 *
 * @param client the client whose cache to evict from
 **/
static void treefile_evict_one(CLIENT *client) {
	struct treefile_entry entry;

	if (!g_hash_table_find(client->treefdcache, treefile_find_one, &entry))
		return;
	g_hash_table_remove(client->treefdcache, &entry.blocknr);
	close(entry.fd);
}

/**
 * Get a file descriptor for the block file holding the data at a given
 * offset of a treefiles export. The block file is opened (and, if
 * create is set, created together with the directories leading to it)
 * on first use; the descriptor is then cached for subsequent accesses
 * to the same block.
 *
 * @param client the client whose export we're serving
 * @param pos a byte offset into the export
 * @param create whether the block file may be created if it does not
 * exist yet
 * @return a file descriptor for the block file, or -1 if the block file
 * does not exist (and may not be created) or could not be opened
 **/
int treefile_getfd(CLIENT *client, off_t pos, int create) {
	uint64_t blocknr = pos / TREEPAGESIZE;
	uint64_t *key;
	gpointer value;
	mode_t mode;
	int fd;

	pthread_mutex_lock(&client->treefile_lock);
	if (g_hash_table_lookup_extended(client->treefdcache, &blocknr,
				NULL, &value)) {
		pthread_mutex_unlock(&client->treefile_lock);
		return GPOINTER_TO_INT(value);
	}
	pthread_mutex_unlock(&client->treefile_lock);

	mode = (client->server->flags & F_READONLY) ? O_RDONLY : O_RDWR;
	if (create)
		mode |= O_CREAT;
	fd = open_treefile(client->exportname, mode,
			(off_t)client->exportsize, pos,
			&client->treefile_lock);
	if (fd < 0)
		return -1;

	key = g_new(uint64_t, 1);
	*key = blocknr;
	pthread_mutex_lock(&client->treefile_lock);
	if (g_hash_table_lookup_extended(client->treefdcache, &blocknr,
				NULL, &value)) {
		/* another thread opened the same block first */
		pthread_mutex_unlock(&client->treefile_lock);
		g_free(key);
		close(fd);
		return GPOINTER_TO_INT(value);
	}
	if (g_hash_table_size(client->treefdcache) >= TREEFILE_MAX_FDS)
		treefile_evict_one(client);
	g_hash_table_insert(client->treefdcache, key, GINT_TO_POINTER(fd));
	pthread_mutex_unlock(&client->treefile_lock);

	return fd;
}

/**
 * Remove a block from the descriptor cache of a client, closing its
 * file descriptor.
 *
 * @param client the client whose cache to update
 * @param blocknr the number of the block to drop
 **/
static void treefile_drop_block(CLIENT *client, uint64_t blocknr) {
	gpointer value;

	pthread_mutex_lock(&client->treefile_lock);
	if (g_hash_table_lookup_extended(client->treefdcache, &blocknr,
				NULL, &value)) {
		close(GPOINTER_TO_INT(value));
		g_hash_table_remove(client->treefdcache, &blocknr);
	}
	pthread_mutex_unlock(&client->treefile_lock);
}

/**
 * Handle a TRIM request on a treefiles export: delete the block files
 * of all blocks fully covered by the trimmed range.
 *
 * @param req the request to process
 * @param client the client we're serving
 * @return 0 on success, nonzero on failure
 **/
int treefiles_trim(struct nbd_request *req, CLIENT *client) {
	uint64_t first = (req->from + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t past_last = (req->from + req->len) / TREEPAGESIZE;
	uint64_t blocknr;

	for (blocknr = first; blocknr < past_last; blocknr++) {
		treefile_drop_block(client, blocknr);
		delete_treefile(client->exportname,
				(off_t)client->exportsize,
				blocknr * TREEPAGESIZE);
	}
	DEBUG("Performed TRIM on treefiles export from %llu to %llu\n",
			(unsigned long long)req->from,
			(unsigned long long)req->len);
	return 0;
}

/**
 * Zero out part of a treefiles export by writing to the affected block
 * files, creating them if necessary.
 *
 * @param client the client we're serving
 * @param pos the offset where the range to zero starts
 * @param len the length of the range to zero
 * @return 0 on success, nonzero on failure
 **/
static int treefile_zero_range(CLIENT *client, uint64_t pos, uint64_t len) {
	char zeros[TREEPAGESIZE];

	memset(zeros, 0, sizeof(zeros));
	while (len > 0) {
		size_t chunk = TREEPAGESIZE - (pos % TREEPAGESIZE);
		int fd;

		if (chunk > len)
			chunk = len;
		fd = treefile_getfd(client, (off_t)pos, 1);
		if (fd < 0 || pwrite(fd, zeros, chunk,
				pos % TREEPAGESIZE) != (ssize_t)chunk)
			return -1;
		pos += chunk;
		len -= chunk;
	}
	return 0;
}

/**
 * Handle a WRITE_ZEROES request on a treefiles export: delete the block
 * files of all blocks fully covered by the request, and zero out any
 * partially covered blocks.
 *
 * @param req the request to process
 * @param client the client we're serving
 * @param fua flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
int treefiles_write_zeroes(struct nbd_request *req, CLIENT *client, int fua) {
	uint64_t from = req->from;
	uint64_t end = req->from + req->len;
	uint64_t first_full = (from + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t past_last_full = end / TREEPAGESIZE;
	uint64_t blocknr;

	if (first_full >= past_last_full) {
		/* no block is fully covered; zero the range in place */
		return treefile_zero_range(client, from, req->len);
	}
	if (from < first_full * TREEPAGESIZE &&
			treefile_zero_range(client, from,
				first_full * TREEPAGESIZE - from))
		return -1;
	for (blocknr = first_full; blocknr < past_last_full; blocknr++) {
		treefile_drop_block(client, blocknr);
		delete_treefile(client->exportname,
				(off_t)client->exportsize,
				blocknr * TREEPAGESIZE);
	}
	if (past_last_full * TREEPAGESIZE < end &&
			treefile_zero_range(client,
				past_last_full * TREEPAGESIZE,
				end - past_last_full * TREEPAGESIZE))
		return -1;

	if ((client->server->flags & F_SYNC) || fua)
		return treefiles_flush(client);
	return 0;
}

static void treefile_fsync_cb(gpointer key, gpointer value, gpointer user_data) {
	if (fsync(GPOINTER_TO_INT(value)) < 0)
		*(int *)user_data = -1;
}

/**
 * Handle a FLUSH request on a treefiles export: fsync all cached block
 * file descriptors.
 *
 * @param client the client we're serving
 * @return 0 on success, nonzero on failure
 **/
int treefiles_flush(CLIENT *client) {
	int ret = 0;

	pthread_mutex_lock(&client->treefile_lock);
	g_hash_table_foreach(client->treefdcache, treefile_fsync_cb, &ret);
	pthread_mutex_unlock(&client->treefile_lock);
	return ret;
}

