/*
 * Minimal NBD protocol probe client for verifying nbd-server behavior
 * (used to verify the treefiles implementation). Speaks fixed new-style
 * negotiation with NBD_OPT_EXPORT_NAME and supports read (with pattern
 * verification), write, trim, write_zeroes, flush and disconnect.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>
#include <endian.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>

#define INIT_MAGIC 0x00420281861253ULL
#define OPT_MAGIC 0x49484156454F5054ULL
#define REQ_MAGIC 0x25609513u
#define REP_MAGIC 0x67446698u
#define NBD_OPT_EXPORT_NAME 1
#define NBD_FLAG_C_FIXED_NEWSTYLE (1 << 0)
#define NBD_FLAG_C_NO_ZEROES (1 << 1)
#define NBD_CMD_READ 0
#define NBD_CMD_WRITE 1
#define NBD_CMD_DISC 2
#define NBD_CMD_FLUSH 3
#define NBD_CMD_TRIM 4
#define NBD_CMD_WRITE_ZEROES 6

static int sock = -1;

static void rd(void *buf, size_t len) {
	size_t off = 0;
	while (off < len) {
		ssize_t r = read(sock, (char *)buf + off, len - off);
		if (r <= 0) {
			fprintf(stderr, "E: short read: %s\n",
				r ? strerror(errno) : "EOF");
			exit(2);
		}
		off += r;
	}
}

static void wr(const void *buf, size_t len) {
	size_t off = 0;
	while (off < len) {
		ssize_t w = write(sock, (const char *)buf + off, len - off);
		if (w <= 0) {
			fprintf(stderr, "E: short write: %s\n", strerror(errno));
			exit(2);
		}
		off += w;
	}
}

static void fill_pattern(char *buf, size_t len, uint64_t off, uint32_t seed) {
	size_t i;
	for (i = 0; i < len; i++)
		buf[i] = (char)((((off + i) >> 9) + seed) & 0xFF);
}

/* cookie doubles as a request counter */
static uint64_t cookiecnt = 1;

static void send_req(uint32_t type, uint64_t from, uint32_t len) {
	struct {
		uint32_t magic;
		uint32_t type;
		uint64_t cookie;
		uint64_t from;
		uint32_t len;
	} __attribute__((packed)) req;

	req.magic = htonl(REQ_MAGIC);
	req.type = htonl(type);
	req.cookie = htobe64(cookiecnt++);
	req.from = htobe64(from);
	req.len = htonl(len);
	wr(&req, sizeof(req));
}

static uint32_t recv_rep(uint64_t expect_cookie) {
	struct {
		uint32_t magic;
		uint32_t error;
		uint64_t cookie;
	} __attribute__((packed)) rep;

	rd(&rep, sizeof(rep));
	if (ntohl(rep.magic) != REP_MAGIC) {
		fprintf(stderr, "E: bad reply magic %x\n", ntohl(rep.magic));
		exit(2);
	}
	if (be64toh(rep.cookie) != expect_cookie) {
		fprintf(stderr, "E: cookie mismatch\n");
		exit(2);
	}
	return ntohl(rep.error);
}

static void do_write(uint64_t off, uint32_t len, uint32_t seed) {
	char *buf = malloc(len);

	fill_pattern(buf, len, off, seed);
	send_req(NBD_CMD_WRITE, off, len);
	wr(buf, len);
	uint32_t err = recv_rep(cookiecnt - 1);
	if (err) {
		fprintf(stderr, "E: write error %u\n", err);
		exit(1);
	}
	free(buf);
	printf("write %llu+%u ok\n", (unsigned long long)off, len);
}

static void do_read(uint64_t off, uint32_t len, uint32_t seed, int zero) {
	char *buf = malloc(len);
	char *exp = malloc(len);

	if (zero)
		memset(exp, 0, len);
	else
		fill_pattern(exp, len, off, seed);
	send_req(NBD_CMD_READ, off, len);
	uint32_t err = recv_rep(cookiecnt - 1);
	if (err) {
		fprintf(stderr, "E: read error %u\n", err);
		exit(1);
	}
	rd(buf, len);
	if (memcmp(buf, exp, len)) {
		size_t i;
		for (i = 0; i < len; i++)
			if (buf[i] != exp[i])
				break;
		fprintf(stderr,
			"E: data mismatch at export offset %llu: got %02x want %02x\n",
			(unsigned long long)(off + i),
			(unsigned char)buf[i], (unsigned char)exp[i]);
		exit(1);
	}
	free(buf);
	free(exp);
	printf("read %llu+%u ok%s\n", (unsigned long long)off, len,
	       zero ? " (zeroes)" : "");
}

static void do_cmd(uint32_t type, const char *name, uint64_t off, uint32_t len) {
	send_req(type, off, len);
	uint32_t err = recv_rep(cookiecnt - 1);
	if (err) {
		fprintf(stderr, "E: %s error %u\n", name, err);
		exit(1);
	}
	printf("%s %llu+%u ok\n", name, (unsigned long long)off, len);
}

int main(int argc, char **argv) {
	struct addrinfo hints, *ai;
	int argi;

	if (argc < 4) {
		fprintf(stderr,
			"usage: %s host port export [write|read|readzero|trim|wzeroes|flush OFF LEN [SEED]]...\n",
			argv[0]);
		return 2;
	}

	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	if (getaddrinfo(argv[1], argv[2], &hints, &ai)) {
		perror("getaddrinfo");
		return 2;
	}
	sock = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
	if (sock < 0 || connect(sock, ai->ai_addr, ai->ai_addrlen) < 0) {
		perror("connect");
		return 2;
	}
	freeaddrinfo(ai);

