	uint64_t magic;
	rd(&magic, 8);
	if (be64toh(magic) != INIT_MAGIC) {
		fprintf(stderr, "E: bad init magic\n");
		return 2;
	}
	rd(&magic, 8);
	if (be64toh(magic) != OPT_MAGIC) {
		fprintf(stderr, "E: bad opts magic\n");
		return 2;
	}
	uint32_t cflags = htonl(NBD_FLAG_C_FIXED_NEWSTYLE | NBD_FLAG_C_NO_ZEROES);
	wr(&cflags, 4);

	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t len;
	} __attribute__((packed)) opt;
	const char *export = argv[3];
	opt.magic = htobe64(OPT_MAGIC);
	opt.opt = htonl(NBD_OPT_EXPORT_NAME);
	opt.len = htonl(strlen(export));
	wr(&opt, sizeof(opt));
	wr(export, strlen(export));

	uint64_t size;
	uint16_t eflags;
	rd(&size, 8);
	rd(&eflags, 2);
	printf("connected: export size %llu flags %x\n",
	       (unsigned long long)be64toh(size), ntohs(eflags));

	for (argi = 4; argi < argc; argi++) {
		const char *cmd = argv[argi];
		if (!strcmp(cmd, "flush")) {
			do_cmd(NBD_CMD_FLUSH, "flush", 0, 0);
		} else {
			if (argc < argi + 3) {
				fprintf(stderr, "E: %s needs OFF LEN [SEED]\n", cmd);
				return 2;
			}
			uint64_t off = strtoull(argv[argi + 1], NULL, 0);
			uint32_t len = strtoul(argv[argi + 2], NULL, 0);
			uint32_t seed = 0;
			if (argc > argi + 3 && strcmp(cmd, "readzero") != 0
					&& strcmp(cmd, "read") != 0
					&& strcmp(cmd, "write") != 0) {
				seed = strtoul(argv[argi + 3], NULL, 0);
				argi++;
			} else if (argc > argi + 3) {
				seed = strtoul(argv[argi + 3], NULL, 0);
				argi++;
			}
			argi += 2;
			if (!strcmp(cmd, "write"))
				do_write(off, len, seed);
			else if (!strcmp(cmd, "read"))
				do_read(off, len, seed, 0);
			else if (!strcmp(cmd, "readzero"))
				do_read(off, len, 0, 1);
			else if (!strcmp(cmd, "trim"))
				do_cmd(NBD_CMD_TRIM, "trim", off, len);
			else if (!strcmp(cmd, "wzeroes"))
				do_cmd(NBD_CMD_WRITE_ZEROES, "write_zeroes",
				       off, len);
			else {
				fprintf(stderr, "E: unknown command %s\n", cmd);
				return 2;
			}
		}
	}

	send_req(NBD_CMD_DISC, 0, 0);
	close(sock);
	return 0;
}

