/*
 * Tree files support.
 *
 * A treefiles export stores its data in a tree of small fixed-size block
 * files rather than in one large file. The exportname of such an export
 * is a directory; each directory level holds at most TREEDIRSIZE entries,
 * and each block file at the leaves holds TREEPAGESIZE bytes of export
 * data. Depending on the total size of the export, several levels of
 * subdirectories (named TREEXXXX) are nested below the export directory,
 * with the block files (named FILEXXXX) as the leaves of the tree.
 *
 * Block files and the directories leading to them are created on demand
 * when data is written, and block files are removed again when the
 * corresponding block is trimmed or zeroed out. Blocks without a block
 * file read back as all zeroes.
 */

#include "config.h"
#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
