/** maximum size of a buffer holding the full path of a block file */
#define TREE_PATH_MAX 4096

/** maximum number of block file descriptors kept open per client */
#define TREEFILE_MAX_FDS 8192

/** a cached open block file descriptor */
struct treefile_fd {
	int fd;
	int dirty; /**< data was written since the last flush */
};

/**
 * Compute the number of levels of TREEXXXX subdirectories needed for an
 * export of the given size. If the export holds at most TREEDIRSIZE
 * blocks, no subdirectories are needed and the block files live directly
 * below the export directory.
 *
 * @param size the total size of the export in bytes
 * @return the number of directory levels between the export directory
 * and the block files
 **/
static int tree_depth(off_t size) {
	uint64_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t capacity = TREEDIRSIZE;
	int depth = 0;

	while (capacity < blocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}
	return depth;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of a treefiles export. The path is appended to the directory
 * already contained in the name buffer.
 *
 * @param name on input a buffer holding the path of the export
 * directory, on output a buffer holding the full path of the block file
 * @param lenmax the size of the name buffer
 * @param size the total size of the export in bytes
 * @param pos a byte offset into the export
 * @param ppos if not NULL, receives the offset of pos within the block
 * file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	uint64_t blocknr = pos / TREEPAGESIZE;
	int depth = tree_depth(size);
	uint64_t divisor = 1;
	int len = strlen(name);
	int i;

	for (i = 0; i < depth; i++)
		divisor *= TREEDIRSIZE;

	for (i = depth; i >= 0; i--) {
		unsigned int entry = (blocknr / divisor) % TREEDIRSIZE;

		if (i > 0)
			snprintf(name + len, lenmax - len, "/TREE%04X", entry);
		else
			snprintf(name + len, lenmax - len, "/FILE%04X", entry);
		len = strlen(name);
		divisor /= TREEDIRSIZE;
	}

	if (ppos)
		*ppos = pos % TREEPAGESIZE;
}

/**
 * Create all directories in the given path. Existing directories are
 * silently left alone.
 *
 * @param path the path whose directory components should be created;
 * temporarily modified by this function
 **/
void mkdir_path(char *path) {
	char *p = path;

	while ((p = strchr(p + 1, '/')) != NULL) {
		*p = '\0';
		mkdir(path, 0700);
		*p = '/';
	}
	mkdir(path, 0700);
}

/**
 * Open the block file holding the data at a given offset of a treefiles
 * export. The directories leading to the block file are created if they
 * do not exist yet.
 *
 * @param name the path of the export directory
 * @param mode open mode for the block file; if it contains O_CREAT, the
 * file is created (or truncated to the size of the data it should hold)
 * when it does not exist yet
 * @param size the total size of the export in bytes
 * @param pos a byte offset into the export
 * @param mutex mutex serializing directory and file creation between
 * threads
 * @return a file descriptor for the block file, or -1 in case of error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[TREE_PATH_MAX];
	char *lastsep;
	off_t ppos;
	int depth;
	int fd;

	depth = tree_depth(size);
	/* every tree level adds a "/TREEXXXX" or "/FILEXXXX" component */
	if (strlen(name) + (depth + 1) * 9 + 1 > sizeof(path)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);

	lastsep = strrchr(path, '/');
	*lastsep = '\0';
	pthread_mutex_lock(mutex);
	mkdir_path(path);
	*lastsep = '/';
	fd = open(path, mode, 0600);
	if (fd >= 0 && (mode & O_CREAT)) {
		/* give the block file the size of the data it should
		 * hold, so that reads of never-written data at the end
		 * of the export succeed */
		off_t blockstart = (pos / TREEPAGESIZE) * TREEPAGESIZE;
		off_t blocklen = TREEPAGESIZE;

		if (size - blockstart < blocklen)
			blocklen = size - blockstart;
		while (ftruncate(fd, blocklen) < 0) {
			if (errno == EINTR)
				continue;
			close(fd);
			fd = -1;
			break;
		}
	}
	pthread_mutex_unlock(mutex);

	return fd;
}

/**
 * Delete the block file holding the data at a given offset of a
 * treefiles export. It is not an error if the block file does not
 * exist.
 *
 * @param name the path of the export directory
 * @param size the total size of the export in bytes
 * @param pos a byte offset into the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[TREE_PATH_MAX];
	off_t ppos;

	if (strlen(name) + (tree_depth(size) + 1) * 9 + 1 > sizeof(path))
		return;
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);
	if (unlink(path) < 0 && errno != ENOENT)
		DEBUG("could not delete treefile %s: %s\n", path, strerror(errno));
}

