/**
 * Drop one arbitrary entry from the descriptor cache to keep the number
 * of open file descriptors bounded. The caller must hold
 * client->treefile_lock.
 *
 * @param client the client whose cache to evict from
 **/
static void treefile_evict_one(CLIENT *client) {
	struct treefile_entry entry;

	if (!g_hash_table_find(client->treefdcache, treefile_find_one, &entry))
		return;
