static void treefile_drop_block(CLIENT *client, uint64_t blocknr) {
	gpointer value;

	pthread_mutex_lock(&client->treefile_lock);
	if (g_hash_table_lookup_extended(client->treefdcache, &blocknr,
				NULL, &value)) {
