/**
 * Handle a TRIM request on a treefiles export: delete the block files
 * of all blocks fully covered by the trimmed range.
 *
 * @param req the request to process
 * @param client the client we're serving
 * @return 0 on success, nonzero on failure
 **/
int treefiles_trim(struct nbd_request *req, CLIENT *client) {
	uint64_t first = (req->from + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t past_last = (req->from + req->len) / TREEPAGESIZE;
	uint64_t blocknr;

	for (blocknr = first; blocknr < past_last; blocknr++) {
		treefile_drop_block(client, blocknr);
		delete_treefile(client->exportname,
				(off_t)client->exportsize,
				blocknr * TREEPAGESIZE);
	}
	DEBUG("Performed TRIM on treefiles export from %llu to %llu\n",
			(unsigned long long)req->from,
			(unsigned long long)req->len);
	return 0;
}

/**
 * Zero out part of a treefiles export by writing to the affected block
 * files, creating them if necessary.
 *
 * @param client the client we're serving
 * @param pos the offset where the range to zero starts
 * @param len the length of the range to zero
 * @return 0 on success, nonzero on failure
 **/
static int treefile_zero_range(CLIENT *client, uint64_t pos, uint64_t len) {
	char zeros[TREEPAGESIZE];

	memset(zeros, 0, sizeof(zeros));
	while (len > 0) {
		size_t chunk = TREEPAGESIZE - (pos % TREEPAGESIZE);
		int fd;

		if (chunk > len)
			chunk = len;
		fd = treefile_getfd(client, (off_t)pos, 1);
		if (fd < 0 || pwrite(fd, zeros, chunk,
				pos % TREEPAGESIZE) != (ssize_t)chunk)
			return -1;
		pos += chunk;
		len -= chunk;
	}
	return 0;
}

/**
 * Handle a WRITE_ZEROES request on a treefiles export: delete the block
 * files of all blocks fully covered by the request, and zero out any
 * partially covered blocks.
 *
 * @param req the request to process
 * @param client the client we're serving
 * @param fua flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
int treefiles_write_zeroes(struct nbd_request *req, CLIENT *client, int fua) {
	uint64_t from = req->from;
	uint64_t end = req->from + req->len;
	uint64_t first_full = (from + TREEPAGESIZE - 1) / TREEPAGESIZE;
	uint64_t past_last_full = end / TREEPAGESIZE;
	uint64_t blocknr;

	if (first_full >= past_last_full) {
		/* no block is fully covered; zero the range in place */
		return treefile_zero_range(client, from, req->len);
	}
	if (from < first_full * TREEPAGESIZE &&
			treefile_zero_range(client, from,
				first_full * TREEPAGESIZE - from))
		return -1;
	for (blocknr = first_full; blocknr < past_last_full; blocknr++) {
		treefile_drop_block(client, blocknr);
		delete_treefile(client->exportname,
				(off_t)client->exportsize,
				blocknr * TREEPAGESIZE);
	}
	if (past_last_full * TREEPAGESIZE < end &&
			treefile_zero_range(client,
				past_last_full * TREEPAGESIZE,
				end - past_last_full * TREEPAGESIZE))
		return -1;

	if ((client->server->flags & F_SYNC) || fua)
		return treefiles_flush(client);
	return 0;
}

static void treefile_collect_dirty(gpointer key, gpointer value, gpointer user_data) {
	struct treefile_fd *tfd = value;
	GArray *fds = user_data;

	if (tfd->dirty) {
		tfd->dirty = 0;
		g_array_append_val(fds, tfd->fd);
	}
}

/**
 * Handle a FLUSH request on a treefiles export: fsync all cached block
 * files that have been written to since the last flush.
 *
 * @param client the client we're serving
 * @return 0 on success, nonzero on failure
 **/
int treefiles_flush(CLIENT *client) {
	GArray *fds = g_array_new(FALSE, FALSE, sizeof(int));
	guint i;
	int ret = 0;

	pthread_mutex_lock(&client->treefile_lock);
	g_hash_table_foreach(client->treefdcache, treefile_collect_dirty, fds);
	pthread_mutex_unlock(&client->treefile_lock);

	/* the actual syncing happens outside the lock, so that readers
	 * and writers are not blocked by it */
	for (i = 0; i < fds->len; i++) {
		if (fsync(g_array_index(fds, int, i)) < 0 && errno != EBADF)
			ret = -1;
	}
	g_array_free(fds, TRUE);
	return ret;
}

