/**
 * Close all cached block file descriptors of a client and free its
 * treefiles state. Does nothing if the state was never initialized.
 *
 * @param client the client whose state to free
 **/
void treefiles_client_free(CLIENT *client) {
	if (!client->treefdcache)
		return;
	g_hash_table_foreach_remove(client->treefdcache,
			treefile_close_cb, NULL);
	g_hash_table_destroy(client->treefdcache);
	client->treefdcache = NULL;
	pthread_mutex_destroy(&client->treefile_lock);
}

